const observer=new IntersectionObserver((e=>{e.forEach((e=>{e.isIntersecting&&(e.target.classList.add("fade-in"),observer.unobserve(e.target))}))}));document.querySelectorAll(".product-card").forEach((e=>{observer.observe(e)})),document.addEventListener("DOMContentLoaded",(()=>{const e=document.querySelector(".testimonial-slider");Array.from(e.children).forEach((r=>{const o=r.cloneNode(!0);e.appendChild(o)}))}));